export {}; // Make this a module
import type { VitePluginConfig } from './src/Config.js';

declare global {
  // This allows TypeScript to pick up the magic constants that's auto-generated by Forge's Vite
  // plugin that tells the Electron app where to look for the Vite-bundled app code (depending on
  // whether you're running in development or production).
  /**
   * The Vite dev server URL for the renderer named `main_window`, while
   * running `electron-forge start`; `undefined` in a packaged app.
   *
   * Forge defines a `<NAME>_VITE_DEV_SERVER_URL` constant for every entry in
   * {@link VitePluginConfig.renderer}: the renderer's `name` upper-cased,
   * with `-` replaced by `_`. The declared type is `string`, so check it
   * before use.
   *
   * @example
   * ```ts
   * if (MAIN_WINDOW_VITE_DEV_SERVER_URL) {
   *   mainWindow.loadURL(MAIN_WINDOW_VITE_DEV_SERVER_URL);
   * } else {
   *   mainWindow.loadFile(path.join(__dirname, `../renderer/${MAIN_WINDOW_VITE_NAME}/index.html`));
   * }
   * ```
   */
  const MAIN_WINDOW_VITE_DEV_SERVER_URL: string;
  /**
   * The name of the renderer named `main_window`, which is also the folder
   * its built files are in, for loading them from a packaged app.
   *
   * Forge defines a `<NAME>_VITE_NAME` constant for every entry in
   * {@link VitePluginConfig.renderer}.
   */
  const MAIN_WINDOW_VITE_NAME: string;

  interface VitePluginRuntimeKeys {
    VITE_DEV_SERVER_URL: `${string}_VITE_DEV_SERVER_URL`;
    VITE_NAME: `${string}_VITE_NAME`;
  }
}

declare module 'vite' {
  interface ConfigEnv<K extends 'build' | 'renderer' = 'build' | 'renderer'> {
    root: string;
    forgeConfig: VitePluginConfig;
    forgeConfigSelf: VitePluginConfig[K][number];
    /** @internal */
    electronTargets?: { node?: string; chrome?: string };
  }
}
